import fs from 'node:fs';import crypto from 'node:crypto';
// Owner 24.10: a replaced photo keeps its file name, so a phone kept showing the old one. Each local photo gets ?v= from its
// own content: a new photo means a new address, and the phone loads it at once. Regenerated by `npm run build:pages`.
const dir=new URL('../public/media/',import.meta.url);
export function mediaVersionsSource(){const v={};for(const f of fs.readdirSync(dir).filter(f=>f.endsWith('.jpg')).sort())v[f.slice(0,-4)]=crypto.createHash('sha256').update(fs.readFileSync(new URL(f,dir))).digest('hex').slice(0,8);
 return '// Generated by tools/media-versions.mjs from public/media — do not edit by hand.\nexport const mediaVersions='+JSON.stringify(v)+';\n'}
if(import.meta.url===`file://${process.argv[1]}`)fs.writeFileSync(new URL('../public/media-versions.js',import.meta.url),mediaVersionsSource());
